        if rows:
            r0 = rows[0]
            print("  row keys:", list(r0.keys()))
            if "steps" in r0 and r0["steps"]:
                print("  step[0] keys:", list(r0["steps"][0].keys()))
            tool_errs = Counter()
            family_scores = {}
            for r in rows:
                for s in r.get("steps", [r]):
                    err = s.get("tool_error")
                    if err:
                        tool_errs[err] += 1
                    for t in s.get("trajectory_trace", []):
                        if t.get("tool_error"):
                            tool_errs[t.get("tool_error")] += 1
                    tf = s.get("task_family") or r.get("task_family")
                    if tf:
                        family_scores.setdefault(tf, []).append(r.get("score", 0.0))
            print("  tool_errors:", tool_errs.most_common(10))
            for tf, sc in sorted(family_scores.items()):
                print(f"  family {tf}: {sum(sc)/len(sc):.3f} ({sum(sc):.0f}/{len(sc)})")
